const inputItems = $input.all();
const sprints = inputItems.flatMap(item => (item.json && item.json.values) || []);
const now = new Date();
const ended = sprints.filter(s => s.endDate && new Date(s.endDate) < now).sort((a, b) => new Date(b.endDate) - new Date(a.endDate));
const current = ended[0] || null;
const previous = ended[1] || null;
const items = [];
if (current) {
  items.push({ json: { sprintId: current.id, sprintName: current.name, sprintState: 'closed', startDate: current.startDate, endDate: current.endDate, goal: current.goal || '' }});
}
if (previous) {
  items.push({ json: { sprintId: previous.id, sprintName: previous.name, sprintState: 'closed', startDate: previous.startDate, endDate: previous.endDate, goal: previous.goal || '' }});
}
return items;

const sprintMeta = $('Extraer Sprint IDs').all();
const issuesData = $input.all();
const fecha = new Date().toLocaleString('es-CL', { timeZone: 'America/Santiago' });

const formatDate = (iso) => { if (!iso) return '-'; const d = new Date(iso); return `${String(d.getDate()).padStart(2,'0')}-${String(d.getMonth()+1).padStart(2,'0')}-${d.getFullYear()}`; };

const CATEGORIES = [
  { key: 'POR HACER', color: '#64748B', bg: '#F1F5F9' },
  { key: 'EN CURSO', color: '#2563EB', bg: '#EFF6FF' },
  { key: 'CODE REVIEW', color: '#7C3AED', bg: '#F5F3FF' },
  { key: 'LISTO PARA QA', color: '#0EA5E9', bg: '#F0F9FF' },
  { key: 'QA', color: '#F59E0B', bg: '#FFFBEB' },
  { key: 'CON IMPEDIMIENTO', color: '#DC2626', bg: '#FEF2F2' },
  { key: 'LISTO PARA DESPLIEGUE', color: '#4F46E5', bg: '#EEF2FF' },
  { key: 'LISTO', color: '#16A34A', bg: '#F0FDF4' }
];

const mapStatus = (s) => {
  const t = (s || '').toLowerCase();
  if (t.includes('impedimento')) return 'CON IMPEDIMIENTO';
  if (t.includes('finalizada') || t.includes('done')) return 'LISTO';
  if (t.includes('despliegue') || t.includes('deploy')) return 'LISTO PARA DESPLIEGUE';
  if (t.includes('code review') || t.includes('review')) return 'CODE REVIEW';
  if (t.includes('listo para qa') || t.includes('ready for qa')) return 'LISTO PARA QA';
  if (t.includes('qa')) return 'QA';
  if (t.includes('curso') || t.includes('progress')) return 'EN CURSO';
  return 'POR HACER';
};

function getIssueSprintIds(issue) {
  const ids = new Set();
  for (const [k, v] of Object.entries(issue.fields)) {
    if ((k === 'closedSprints' || k.startsWith('customfield_')) && Array.isArray(v)) {
      for (const s of v) {
        if (s && typeof s === 'object' && s.id !== undefined && s.state !== undefined) ids.add(s.id);
      }
    }
  }
  return ids;
}

// Sprint actual: usa estado actual de Jira (es el sprint en curso o recien cerrado)
function calcMetrics(issues, sprint, sprintId) {
  issues = issues.filter(i => getIssueSprintIds(i).has(sprintId));
  const total = issues.length;
  const counts = {};
  CATEGORIES.forEach(c => counts[c.key] = 0);
  let bugs = 0, spillover = 0, scopeCreep = 0, escapedDefects = 0;
  const spilloverList = [], escapedList = [];

  for (const issue of issues) {
    const cat = mapStatus(issue.fields.status ? issue.fields.status.name : '');
    counts[cat] = (counts[cat] || 0) + 1;

    const typeName = issue.fields.issuetype ? issue.fields.issuetype.name : '';
    if (typeName.toLowerCase().includes('bug') || typeName.toLowerCase().includes('error')) bugs++;

    const labels = issue.fields.labels || [];
    if (labels.some(l => /^produccion_portalpacientes$/i.test((l || '').normalize('NFD').replace(/[̀-ͯ]/g, '').trim()))) {
      escapedDefects++;
      escapedList.push({ key: issue.key, titulo: issue.fields.summary, estado: issue.fields.status ? issue.fields.status.name : '-' });
    }

    let closedSprints = [];
    if (issue.fields.closedSprints && Array.isArray(issue.fields.closedSprints)) closedSprints = issue.fields.closedSprints;
    if (closedSprints.length === 0) {
      for (const [k, v] of Object.entries(issue.fields)) {
        if (k.startsWith('customfield_') && Array.isArray(v) && v.length > 0 && v[0] && v[0].state === 'closed') { closedSprints = v; break; }
      }
    }
    const otherSprints = closedSprints.filter(s => s.id !== sprintId);
    if (otherSprints.length > 0) {
      spillover++;
      const lastOther = otherSprints[otherSprints.length - 1];
      spilloverList.push({ key: issue.key, titulo: issue.fields.summary, sprintOrigen: lastOther.name || '-' });
    }

    if (sprint.startDate) {
      const created = new Date(issue.fields.created);
      const sprintStart = new Date(sprint.startDate);
      if (created > sprintStart) scopeCreep++;
    }
  }

  const completado = counts['LISTO'];
  const pctCompletado = total > 0 ? Math.round((completado / total) * 100) : 0;
  const spilloverRate = total > 0 ? Math.round((spillover / total) * 100) : 0;
  const bugRatio = total > 0 ? Math.round((bugs / total) * 100) : 0;
  const scopeCreepRate = total > 0 ? Math.round((scopeCreep / total) * 100) : 0;
  const goalMet = pctCompletado >= 80;

  const incompleteList = [];
  for (const iss of issues) {
    const ct = mapStatus(iss.fields.status ? iss.fields.status.name : '');
    if (ct !== 'LISTO') {
      const co = CATEGORIES.find(c => c.key === ct);
      incompleteList.push({ key: iss.key, titulo: iss.fields.summary, estado: ct, color: co.color, bg: co.bg });
    }
  }
  return { total, completado, pctCompletado, counts, bugs, bugRatio, spillover, spilloverRate, spilloverList, scopeCreep, scopeCreepRate, escapedDefects, escapedList, goalMet, incompleteList };
}

// Sprint anterior: usa resolutiondate para contar solo tickets cerrados DENTRO del sprint
// Evita que cambios post-cierre alteren los porcentajes historicos
function calcPrevMetrics(issues, sprint, sprintId) {
  issues = issues.filter(i => getIssueSprintIds(i).has(sprintId));
  const total = issues.length;
  const endDate = new Date(sprint.endDate);

  const completado = issues.filter(i => {
    const rd = i.fields.resolutiondate;
    return rd && new Date(rd) <= endDate;
  }).length;
  const pctCompletado = total > 0 ? Math.round((completado / total) * 100) : 0;

  const bugs = issues.filter(i => {
    const t = i.fields.issuetype ? i.fields.issuetype.name : '';
    return t.toLowerCase().includes('bug') || t.toLowerCase().includes('error');
  }).length;
  const bugRatio = total > 0 ? Math.round((bugs / total) * 100) : 0;

  const escapedDefects = issues.filter(i => {
    const labels = i.fields.labels || [];
    return labels.some(l => /^produccion_portalpacientes$/i.test((l || '').normalize('NFD').replace(/[̀-ͯ]/g, '').trim()));
  }).length;

  let spillover = 0;
  for (const issue of issues) {
    let closedSprints = [];
    if (issue.fields.closedSprints && Array.isArray(issue.fields.closedSprints)) closedSprints = issue.fields.closedSprints;
    if (closedSprints.length === 0) {
      for (const [k, v] of Object.entries(issue.fields)) {
        if (k.startsWith('customfield_') && Array.isArray(v) && v.length > 0 && v[0] && v[0].state === 'closed') { closedSprints = v; break; }
      }
    }
    if (closedSprints.filter(s => s.id !== sprintId).length > 0) spillover++;
  }
  const spilloverRate = total > 0 ? Math.round((spillover / total) * 100) : 0;

  let scopeCreep = 0;
  if (sprint.startDate) {
    const sprintStart = new Date(sprint.startDate);
    scopeCreep = issues.filter(i => new Date(i.fields.created) > sprintStart).length;
  }
  const scopeCreepRate = total > 0 ? Math.round((scopeCreep / total) * 100) : 0;

  return { total, completado, pctCompletado, bugs, bugRatio, spillover, spilloverRate, escapedDefects, scopeCreep, scopeCreepRate, goalMet: pctCompletado >= 80 };
}

const currentSprint = sprintMeta[0].json;
const currentIssues = issuesData[0].json.issues || [];
const curr = calcMetrics(currentIssues, currentSprint, currentSprint.sprintId || 0);

let prev = null;
let previousSprint = null;
if (sprintMeta.length > 1 && issuesData.length > 1) {
  previousSprint = sprintMeta[1].json;
  const previousIssues = issuesData[1].json.issues || [];
  prev = calcPrevMetrics(previousIssues, previousSprint, previousSprint.sprintId || 0);
}

const sprintNum = (currentSprint.sprintName.match(/\d+/) || [''])[0];
const prevNum = previousSprint ? (previousSprint.sprintName.match(/\d+/) || [''])[0] : '';

const arrow = (current, previous, lowerIsBetter) => {
  if (previous === null || previous === undefined) return { icon: '', color: '#64748B' };
  if (current === previous) return { icon: '=', color: '#64748B' };
  const better = lowerIsBetter ? current < previous : current > previous;
  return { icon: better ? '↑' : '↓', color: better ? '#16A34A' : '#DC2626' };
};

const goalBadge = curr.goalMet
  ? '<span style="background:#F0FDF4; color:#16A34A; padding:6px 16px; border-radius:12px; font-weight:700; font-size:13px;">✅ CUMPLIDO</span>'
  : '<span style="background:#FEF2F2; color:#DC2626; padding:6px 16px; border-radius:12px; font-weight:700; font-size:13px;">❌ NO CUMPLIDO (' + curr.pctCompletado + '%)</span>';

const subject = 'Portal Pacientes \u{1F3C1} Cierre QA Sprint ' + sprintNum;

function kpiCard(label, value, unit, prevValue, lowerIsBetter) {
  const a = arrow(value, prevValue, lowerIsBetter);
  let valueColor = '#0D1846';
  if (lowerIsBetter) valueColor = value === 0 ? '#16A34A' : '#DC2626';
  let prevColor = a.color;
  if (lowerIsBetter && prevValue !== null && prevValue !== undefined) prevColor = prevValue === 0 ? '#16A34A' : '#DC2626';
  const prevText = prevValue !== null && prevValue !== undefined
    ? `<div style='font-size:12px; color:${prevColor}; margin-top:6px; font-weight:700;'>${a.icon} Sprint ${prevNum}: ${prevValue}${unit}</div>`
    : '';
  return `<td width='20%' style='padding:6px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='background:#FFFFFF; border-radius:8px; border:1px solid #E2E8F0;'><tr><td style='padding:16px 10px; text-align:center;'><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:28px; font-weight:800; color:${valueColor}; line-height:1;'>${value}${unit}</div><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; font-weight:700; letter-spacing:0.5px; color:#64748B; text-transform:uppercase; margin-top:6px;'>${label}</div>${prevText}</td></tr></table></td>`;
}

const kpis = kpiCard('Completado', curr.pctCompletado, '%', prev ? prev.pctCompletado : null, false)
  + kpiCard('Spillover', curr.spillover, '', prev ? prev.spillover : null, true)
  + kpiCard('Escaped Defect', curr.escapedDefects, '', prev ? prev.escapedDefects : null, true)
  + kpiCard('Scope Creep', curr.scopeCreep, '', prev ? prev.scopeCreep : null, true)
  + kpiCard('Defect Rate', curr.bugRatio, '%', prev ? prev.bugRatio : null, true);

const makeProgressBar = (label, pct, completed, total, barColor, borderColor) => {
  return `<table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='background:#FFFFFF; border-radius:6px; box-shadow:0 1px 3px rgba(15,23,42,0.08); border-top:3px solid ${borderColor};'><tr><td style='padding:16px 20px;'><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; font-weight:700; color:${borderColor}; margin-bottom:8px;'>${label}</div><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='background:#F1F5F9; border-radius:8px;'><tr><td style='background:${barColor}; border-radius:8px; height:20px; width:${pct}%; font-size:1px;'>&nbsp;</td><td style='font-size:1px;'>&nbsp;</td></tr></table><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#1E293B; margin-top:8px;'><strong style='color:${barColor};'>${completed}/${total} tickets completados (${pct}%)</strong></div></td></tr></table>`;
};

const currentBar = makeProgressBar(
  '\u{1F3C1} Sprint ' + sprintNum + ' (actual)',
  curr.pctCompletado, curr.completado, curr.total, '#16A34A', '#0747A6'
);

const prevBar = prev
  ? makeProgressBar(
    '\u{1F4CB} Sprint ' + prevNum + ' (anterior · snapshot al cierre)',
    prev.pctCompletado, prev.completado, prev.total, '#2563EB', '#64748B'
  )
  : '';

const progressHtml = `<div style='padding:0 20px 12px;'>${currentBar}</div>`
  + (prev ? `<div style='padding:0 20px 20px;'>${prevBar}</div>` : '');

const cardHtml = (cat) => `<td width='25%' style='padding:3px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='background:${cat.bg}; border-left:3px solid ${cat.color}; border-radius:4px;'><tr><td style='padding:6px 8px;'><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:16px; font-weight:700; color:${cat.color};'>${curr.counts[cat.key]}</div><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:8px; font-weight:700; color:#64748B; text-transform:uppercase;'>${cat.key}</div></td></tr></table></td>`;
const cardsRow1 = CATEGORIES.slice(0,4).map(c => cardHtml(c)).join('');
const cardsRow2 = CATEGORIES.slice(4,8).map(c => cardHtml(c)).join('');

let spilloverHtml = '';
if (curr.spilloverList.length > 0) {
  const rows = curr.spilloverList.map(s => `<tr><td style='padding:8px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; font-weight:600; color:#0747A6;'>${s.key}</td><td style='padding:8px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; color:#1E293B;'>${s.titulo}</td><td style='padding:8px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; color:#475569;'>${s.sprintOrigen}</td></tr>`).join('');
  spilloverHtml = `<div style='padding:0 20px 20px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='background:#FFFFFF; border-radius:6px; box-shadow:0 1px 3px rgba(15,23,42,0.08); border-top:3px solid #F59E0B;'><tr><td style='padding:16px 20px;'><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; font-weight:700; color:#F59E0B; margin-bottom:4px;'>\u{1F504} SPILLOVER</div><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#1E293B; margin-bottom:12px;'><strong>${curr.spillover}</strong> ticket(s) arrastrado(s) (${curr.spilloverRate}%)</div><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='border-collapse:collapse;'><thead><tr style='background:#FEF3C7;'><th align='left' style='padding:6px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#92400E;'>Ticket</th><th align='left' style='padding:6px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#92400E;'>Título</th><th align='left' style='padding:6px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#92400E;'>Sprint Origen</th></tr></thead><tbody>${rows}</tbody></table></td></tr></table></div>`;
}

let escapedHtml = '';
if (curr.escapedList.length > 0) {
  const rows = curr.escapedList.map(e => `<tr><td style='padding:8px 12px; border-bottom:1px solid #FECACA; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; font-weight:600; color:#0747A6;'>${e.key}</td><td style='padding:8px 12px; border-bottom:1px solid #FECACA; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; color:#1E293B;'>${e.titulo}</td><td style='padding:8px 12px; border-bottom:1px solid #FECACA; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; color:#475569;'>${e.estado}</td></tr>`).join('');
  escapedHtml = `<div style='padding:0 20px 20px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='background:#FFFFFF; border-radius:6px; box-shadow:0 1px 3px rgba(15,23,42,0.08); border-top:3px solid #DC2626;'><tr><td style='padding:16px 20px;'><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; font-weight:700; color:#DC2626; margin-bottom:4px;'>\u{1F41B} ESCAPED DEFECTS</div><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#1E293B; margin-bottom:12px;'><strong>${curr.escapedDefects}</strong> bug(s) encontrado(s) en producción</div><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='border-collapse:collapse;'><thead><tr style='background:#FEE2E2;'><th align='left' style='padding:6px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#991B1B;'>Ticket</th><th align='left' style='padding:6px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#991B1B;'>Título</th><th align='left' style='padding:6px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#991B1B;'>Estado</th></tr></thead><tbody>${rows}</tbody></table></td></tr></table></div>`;
}

let incompleteHtml = '';
if (curr.incompleteList.length > 0) {
  const incRows = curr.incompleteList.map(t => '<tr>'
    + '<td width="80" style="padding:8px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; font-weight:600; color:#0747A6; white-space:nowrap; min-width:80px;">' + t.key + '</td>'
    + '<td style="padding:8px 12px; border-bottom:1px solid #E2E8F0; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; color:#1E293B;">' + t.titulo + '</td>'
    + '<td style="padding:8px 12px; border-bottom:1px solid #E2E8F0; text-align:center;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" style="display:inline-table;"><tr><td bgcolor="' + t.bg + '" style="padding:4px 12px; border-radius:12px; font-size:11px; font-family:Segoe UI,Helvetica,Arial,sans-serif; white-space:nowrap;"><font color="' + t.color + '"><b>' + t.estado + '</b></font></td></tr></table></td>'
    + '</tr>').join('');
  incompleteHtml = '<div style="padding:0 20px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#FFFFFF; border-radius:6px; box-shadow:0 1px 3px rgba(15,23,42,0.08); border-top:3px solid #64748B;"><tr><td style="padding:16px 20px;"><div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; font-weight:700; color:#64748B; margin-bottom:4px;">\u{1F4CB} TICKETS NO COMPLETADOS</div><div style="font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#1E293B; margin-bottom:12px;"><strong>' + curr.incompleteList.length + '</strong> ticket(s) no finalizaron en el sprint</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;"><thead><tr style="background:#F1F5F9;"><th align="left" style="padding:6px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Ticket</th><th align="left" style="padding:6px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">T\u00edtulo</th><th align="center" style="padding:6px 12px; font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Estado</th></tr></thead><tbody>' + incRows + '</tbody></table></td></tr></table></div>';
}

const vsText = prev ? ' vs Sprint ' + prevNum + ' (anterior)' : '';

const body = `<div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; max-width:760px; margin:0 auto; background:#F4F6FB;'>`
  + `<table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='background-color:#0D1846;'><tr><td style='padding:28px;'>`
  + `<div style='color:rgba(255,255,255,0.6); font-size:11px; letter-spacing:3px; text-transform:uppercase; font-weight:700;'>REPORTE FINAL QA · BOARD PP</div>`
  + `<div style='color:#FFFFFF; font-size:22px; font-weight:700; margin-top:8px;'>\u{1F3C1} Sprint ${sprintNum} (actual)${vsText}</div>`
  + `<div style='color:rgba(255,255,255,0.7); font-size:13px; margin-top:6px;'>${currentSprint.goal || ''}</div>`
  + `<div style='margin-top:12px;'>${goalBadge}</div>`
  + `</td></tr></table>`
  + progressHtml
  + `<div style='padding:4px 20px 8px;'><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; font-weight:700; color:#64748B; letter-spacing:1.5px; text-transform:uppercase; border-bottom:2px solid #E2E8F0; padding-bottom:6px;'>MÉTRICAS SPRINT ${sprintNum}${prev ? ' vs SPRINT ' + prevNum : ''}</div></div>`
  + `<table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='padding:0 14px 16px;'><tr>${kpis}</tr></table>`
  + `<div style='padding:4px 20px 8px;'><div style='font-family:Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; font-weight:700; color:#64748B; letter-spacing:1.5px; text-transform:uppercase; border-bottom:2px solid #E2E8F0; padding-bottom:6px;'>DETALLE SPRINT ${sprintNum}</div></div>`
  + `<table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='padding:0 17px 12px;'><tr>${cardsRow1}</tr><tr>${cardsRow2}</tr></table>`
  + incompleteHtml
  + escapedHtml
  + spilloverHtml
  + `<div style='padding:14px 20px; font-size:11px; color:#94A3B8; text-align:center; border-top:1px solid #E2E8F0;'>Generado manualmente — WF-5 Reporte Final QA Sprint · Portal Pacientes · ${fecha}</div></div>`;

return [{ json: { subject, body } }];
